mapper.select:
select k.commission_id, k.member_id, k.order_id, k.order_no, k.level, k.amount, k.status, k.remark,
       k.settle_time, k.create_time,
       m.nickname as member_name, m.phone as member_phone, o.product_title
from hys_commission k
left join hys_member m on m.member_id = k.member_id
left join hys_order o on o.order_id = k.order_id

    and k.member_id = #{memberId}
    and k.level = #{level}
    and k.status = #{status}
    and k.order_no like concat('%', #{orderNo}, '%')

        and k.create_time >= #{params.beginTime}


        and k.create_time <= concat(#{params.endTime}, ' 23:59:59')


order by k.commission_id desc

select coalesce(sum(amount), 0) from hys_commission
where member_id = #{memberId}
and level = #{level}
and status = #{status}

select count(1) from hys_commission
where member_id = #{memberId}
and level = #{level}
